WITH reason_returns AS ( SELECT r.r_reason_desc, t.t_shift, t.t_hour, SUM(wr.wr_return_amt) AS total_return_amt, SUM(wr.wr_refunded_cash) AS total_refunded_cash, AVG(wr.wr_net_loss) AS avg_net_loss, COUNT(*) AS return_count FROM web_returns wr JOIN time_dim t ON wr.wr_returned_time_sk = t.t_time_sk JOIN reason r ON wr.wr_reason_sk = r.r_reason_sk WHERE t.t_hour BETWEEN 9 AND 17 AND r.r_reason_desc IN ('Package was damaged', 'Stopped working') GROUP BY r.r_reason_desc, t.t_shift, t.t_hour ) SELECT r.r_reason_desc, r.t_shift, r.t_hour, r.total_return_amt, r.total_refunded_cash, r.avg_net_loss, r.return_count, RANK() OVER (PARTITION BY r.t_shift ORDER BY r.total_return_amt DESC) AS shift_rank, SUM(r.total_return_amt) OVER (PARTITION BY r.t_shift ORDER BY r.t_hour ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_return_amt FROM reason_returns r ORDER BY r.t_shift, shift_rank
